#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn concat(a: &Vec<u64>, b: &Vec<u64>) -> (res: Vec<u64>)
    requires
        a.len() <= 100,
        b.len() <= 100,
    ensures
        res.len() == a.len() + b.len(),
        forall|i: int| 0 <= i < a.len() ==> res[i] == a[i],
        forall|i: int|
            a.len() <= i < res.len() ==> res[i] == b[i - a.len()],
{
    let mut res: Vec<u64> = Vec::new();

    // Copy a
    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i <= a.len(),
            res.len() == i,
            forall|j: int| 0 <= j < i ==> res[j] == a[j],
        decreases a.len() - i
    {
        res.push(a[i]);
        i += 1;
    }

    // Copy b
    let mut k: usize = 0;
    while k < b.len()
        invariant
            0 <= k <= b.len(),
            res.len() == a.len() + k,
            forall|j: int| 0 <= j < a.len() ==> res[j] == a[j],
            forall|j: int|
                a.len() <= j < res.len() ==> res[j] == b[j - a.len()],
        decreases b.len() - k
    {
        res.push(b[k]);
        k += 1;
    }

    res
}

} // verus!